#!/usr/bin/env node
/**
 * Builds everything the extension and the demo load, from the source files in
 * data/ and packages/matcher/.
 *
 *   npm run build              write the generated files
 *   npm run build -- --check   fail if a generated file is out of date (used in CI)
 *
 * Generated files are committed so "Load unpacked" works straight after cloning.
 */
import { createHash } from 'node:crypto';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import path from 'node:path';
import { loadPacks, matcher, root } from './lib/packs.mjs';

const checkOnly = process.argv.includes('--check');

function asScript(globalName, value) {
  return '// Generated by scripts/build.mjs. Do not edit by hand.\n' + `globalThis.${globalName} = ${JSON.stringify(value)};\n`;
}

async function main() {
  const { packs, problems } = await loadPacks();

  const demo = JSON.parse(await readFile(path.join(root, 'demo/demo-bundle.json'), 'utf8'));
  problems.push(...matcher.validateBundle(demo).errors.map((error) => `demo/demo-bundle.json: ${error}`));

  if (problems.length) {
    console.error('Data problems:\n- ' + problems.join('\n- '));
    process.exit(1);
  }

  const body = { catalogVersion: matcher.CATALOG_VERSION, packs: packs.map((pack) => pack.bundle) };
  const listVersion = createHash('sha256').update(JSON.stringify(body)).digest('hex').slice(0, 12);
  const catalog = { catalogVersion: body.catalogVersion, listVersion, packs: body.packs };

  const check = matcher.validateCatalog(catalog);
  if (!check.ok) {
    console.error('Catalog problems:\n- ' + check.errors.join('\n- '));
    process.exit(1);
  }

  const outputs = {
    'extension/data/catalog.json': JSON.stringify(catalog) + '\n',
    'extension/data/catalog.js': asScript('SPOILER_SHIELD_CATALOG', catalog),
    'extension/vendor/matcher.js': await readFile(path.join(root, 'packages/matcher/src/matcher.js'), 'utf8'),
    'demo/demo-bundle.js': asScript('SPOILER_SHIELD_DEMO_BUNDLE', demo),
  };

  const stale = [];
  for (const [relative, content] of Object.entries(outputs)) {
    const file = path.join(root, relative);
    const current = existsSync(file) ? await readFile(file, 'utf8') : null;
    if (current === content) continue;
    if (checkOnly) {
      stale.push(relative);
    } else {
      await mkdir(path.dirname(file), { recursive: true });
      await writeFile(file, content);
      console.log(`wrote ${relative}`);
    }
  }

  if (stale.length) {
    console.error('Out of date, run "npm run build" and commit:\n- ' + stale.join('\n- '));
    process.exit(1);
  }

  const summary = packs.map(({ id, bundle }) => {
    const phrases = bundle.rules.reduce((total, rule) => total + (rule.terms || []).length + (rule.hashes || []).length, 0);
    const count = bundle.chapters.length;
    return `${id} (${count} ${bundle.game.unit}${count === 1 ? '' : 's'}, ${phrases} phrases)`;
  });
  console.log(`${checkOnly ? 'checked' : 'built'} lists ${listVersion}: ${summary.join(', ')}`);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
